    logic signed [PCM_WIDTH:0] biased;   // 25 位，容纳进位
    logic signed [PCM_WIDTH:0] shifted;  // 舍入后的完整值，仍为 25 位
    logic signed [PCM_WIDTH:0] src_ext;  // src 的符号扩展副本
