    begin
        // 关键：必须先把两个操作数都符号扩展到目标位宽再相加。
        // SystemVerilog 中「有符号 24 位 + 无符号常量」会按无符号运算，
        // 负输入会被当成大正数，导致 -8388608 饱和到 +32767 而不是
        // -32768。这里显式扩展，强制走有符号算术。
        // 24 位 -> 25 位只需补 1 位符号位。
        src_ext  = {src[PCM_WIDTH-1], src};
